<script setup lang="ts">import {computed,ref,watch} from 'vue';import {supabase} from '@/lib/supabase'
const q=ref(''),busy=ref(false),products=ref<any[]>([]),customers=ref<any[]>([]),error=ref('');let timer:any
watch(q,()=>{clearTimeout(timer);timer=setTimeout(search,250)})
async function search(){if(!q.value.trim()){products.value=[];customers.value=[];return}busy.value=true;error.value='';const term=`%${q.value.trim()}%`;const [p,c]=await Promise.all([supabase.from('products').select('id,sku,name,category,price_sell,stock').or(`name.ilike.${term},sku.ilike.${term},barcode.ilike.${term}`).limit(30),supabase.from('customers').select('id,name,phone,email').or(`name.ilike.${term},phone.ilike.${term},email.ilike.${term}`).limit(30)]);if(p.error||c.error)error.value=p.error?.message??c.error?.message??'';products.value=p.data??[];customers.value=c.data??[];busy.value=false}
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Search</h1><p>Find products and customers by name, SKU, barcode or contact.</p></div></div><input v-model="q" class="control search" placeholder="Start typing to search…"><p v-if="busy" class="empty">Searching…</p><p v-if="error" class="alert">{{error}}</p><div class="sales-grid mt"><div class="panel"><h2>Products ({{products.length}})</h2><div v-for="p in products" :key="p.id" class="cart-line"><div><b>{{p.name}}</b><small>{{p.sku}} · {{p.category??'Uncategorised'}}</small></div><span>UGX {{Number(p.price_sell).toLocaleString()}} · {{p.stock}} stock</span></div><p v-if="q&&!products.length" class="empty">No matching products.</p></div><div class="panel"><h2>Customers ({{customers.length}})</h2><div v-for="c in customers" :key="c.id" class="cart-line"><div><b>{{c.name}}</b><small>{{c.phone??''}} {{c.email??''}}</small></div></div><p v-if="q&&!customers.length" class="empty">No matching customers.</p></div></div></section></template>
